<?php
namespace App\Reports\Standard;
use App\Reports\Queries\PurchaseReportQuery;use App\Services\Reports\Contracts\StandardReport;use App\Services\Reports\ReportResult;
final class PurchaseByItemReport extends AbstractStandardReport implements StandardReport{
 public function __construct(private readonly PurchaseReportQuery $purchase){}public function code():string{return 'PURCHASE_BY_ITEM';}public function parameters():array{return array_merge($this->periodParameters(),$this->purchaseFilterParameters());}
 public function run(array $p):ReportResult{$m=PurchaseReportQuery::metricSelects();$rows=$this->purchase->postedInvoiceLines($p)->select('i.code as item_code','i.name as item_name','cat.name as category','b.name as brand','bu.code as business_unit')->selectRaw('SUM(l.quantity) AS quantity')->selectRaw('SUM('.$m['purchase_amount'].') AS purchase_amount')->selectRaw('CASE WHEN SUM(l.quantity)<>0 THEN SUM('.$m['purchase_amount'].')/SUM(l.quantity) ELSE 0 END AS average_cost')->groupBy('i.code','i.name','cat.name','b.name','bu.code')->orderByDesc('purchase_amount')->get()->all();return new ReportResult('Purchase by Item',[$this->col('item_code','Item'),$this->col('item_name','Name'),$this->col('category','Category'),$this->col('brand','Brand'),$this->col('business_unit','Business Unit'),$this->col('quantity','Qty','quantity',4),$this->col('purchase_amount','Purchase','money'),$this->col('average_cost','Average Cost','money')],$rows,['Purchase'=>$this->moneySum($rows,'purchase_amount')],['quantity'=>$this->qtySum($rows,'quantity'),'purchase_amount'=>$this->moneySum($rows,'purchase_amount')]);}
}
